"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import { Card } from "@/components/ui/card";
import { CodeBlock, CopyButton } from "@/components/ui/code-block";
import {
  Tabs,
  TabsList,
  TabsTrigger,
  TabsContent,
} from "@/components/ui/tabs";
import { Title, BodySecondary } from "@/components/ui/typography";
export type PreviewProps = React.ComponentProps<"section"> & {
  code: string;
  title?: string;
  description?: string;
  /** Variant selectors or other controls shown with the live specimen. */
  controls?: React.ReactNode;
  /** Optional actions beside the view switcher. */
  actions?: React.ReactNode;
};
export function Preview({
  children,
  code,
  title,
  description,
  controls,
  actions,
  className,
  ...props
}: PreviewProps) {
  return (
    <section
      data-slot="preview"
      className={cn("v-preview", className)}
      {...props}
    >
      {title && <Title as="h3">{title}</Title>}
      {description && <BodySecondary>{description}</BodySecondary>}
      <Tabs defaultValue="preview" variant="underline" className="v-preview__frame">
        <div className="v-preview__toolbar">
          <TabsList aria-label={title ? `${title} view` : "Example view"}>
            <TabsTrigger value="preview">Preview</TabsTrigger>
            <TabsTrigger value="code">Code</TabsTrigger>
          </TabsList>
          <div className="v-preview__actions">
            {actions}
            <CopyButton code={code}>Copy code</CopyButton>
          </div>
        </div>
        <TabsContent value="preview" className="v-preview__panel">
          {controls && <div className="v-preview__controls">{controls}</div>}
          <Card
            variant="cream"
            className="v-preview__canvas"
            style={
              { "--muted-foreground": "var(--v-text-2)" } as React.CSSProperties
            }
          >
            {children}
          </Card>
        </TabsContent>
        <TabsContent value="code" className="v-preview__panel">
          <CodeBlock code={code} language="tsx" title="Example" />
        </TabsContent>
      </Tabs>
    </section>
  );
}

@layer sahajiv-states {
@layer sahajiv-states {
  .v-preview {
    display: grid;
    gap: var(--s-4);
    min-width: 0;
  }
  .v-preview__frame {
    min-width: 0;
    border: 1px solid var(--v-border);
    border-radius: var(--r-card-sm);
    background: var(--v-canvas);
  }
  .v-preview__toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: var(--s-3);
    padding: var(--s-3) var(--s-5);
    border-block-end: 1px solid var(--v-border);
  }
  .v-preview__toolbar > [data-slot="tabs-list"] {
    align-self: stretch;
    align-items: center;
    gap: var(--s-5);
  }
  .v-preview__toolbar > [data-slot="tabs-list"] > [data-slot="tabs-trigger"] {
    min-height: var(--ctl-md);
    padding-block: var(--s-2);
    font-size: var(--fs-control);
  }
  .v-preview__panel {
    min-width: 0;
  }
  .v-preview__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--s-2);
    min-width: 0;
  }
  .v-preview__controls {
    padding: var(--s-4) var(--s-5);
    border-block-end: 1px solid var(--v-border);
  }
  .v-preview .v-preview__canvas {
    display: grid;
    align-content: center;
    min-width: 0;
    min-height: 280px;
    margin: 0;
    overflow: auto;
    padding: clamp(20px, 4vw, 48px);
    border: 0;
    border-radius: 0 0 var(--r-card-sm) var(--r-card-sm);
    background: var(--surface-quiet);
    color: var(--v-text);
  }
  .v-preview__panel > [data-slot="code-block"] {
    border: 0;
    border-radius: 0 0 var(--r-card-sm) var(--r-card-sm);
  }
  @media (max-width: 600px) {
    .v-preview__toolbar,
    .v-preview__controls {
      padding-inline: var(--s-4);
    }
    .v-preview .v-preview__canvas {
      min-height: 240px;
      padding: var(--s-5) var(--s-4);
    }
  }
}

/* Preview joins its tab bar and canvas into one frame. */
[data-slot="tabs"].v-preview__frame { gap: 0; }

}
